/* ============================================================
   POKÉMON ECLIPSE: AURELIA GENESIS — dialogue and menu UI
   ============================================================ */
'use strict';

const UI = (() => {
  const overlay = $('#overlay');
  const dialogue = $('#dialogue');
  const dlgName = $('#dlgName');
  const dlgText = $('#dlgText');
  let active = false;
  let dialogueResolve = null;
  let selected = 0;
  let menuItems = [];
  let menuResolve = null;
  let menuCleanup = null;

  function setText(el, value) { el.textContent = value == null ? '' : String(value); }
  function dismissDialogue() {
    if (!dialogueResolve) return;
    const resolve = dialogueResolve;
    dialogueResolve = null;
    dialogue.classList.add('hidden');
    active = false;
    resolve();
  }
  function onDialogueKey(event) {
    if (!dialogueResolve || !['Enter', ' ', 'z', 'Z'].includes(event.key)) return;
    event.preventDefault();
    event.stopPropagation();
    dismissDialogue();
  }
  document.addEventListener('keydown', onDialogueKey, true);
  dialogue?.addEventListener('click', dismissDialogue);

  function say(text, name = '') {
    if (!dialogue) return Promise.resolve();
    if (dialogueResolve) dismissDialogue();
    active = true;
    setText(dlgName, name);
    setText(dlgText, text);
    dialogue.classList.remove('hidden');
    return new Promise(resolve => { dialogueResolve = resolve; });
  }

  function finishMenu(result) {
    if (!menuResolve) return;
    const resolve = menuResolve;
    menuResolve = null;
    if (menuCleanup) menuCleanup();
    menuCleanup = null;
    if (overlay) {
      overlay.replaceChildren();
      overlay.classList.remove('visible');
    }
    active = false;
    resolve(result);
  }
  function paintSelection() {
    const rows = overlay?.querySelectorAll('[data-menu-index]') || [];
    rows.forEach((row, i) => {
      row.classList.toggle('selected', i === selected);
      row.setAttribute('aria-selected', i === selected ? 'true' : 'false');
    });
  }
  function menuKey(event) {
    if (!menuResolve) return;
    if (event.key === 'ArrowDown' || event.key.toLowerCase() === 's') {
      event.preventDefault(); event.stopPropagation();
      if (menuItems.length) selected = (selected + 1) % menuItems.length;
      paintSelection();
    } else if (event.key === 'ArrowUp' || event.key.toLowerCase() === 'w') {
      event.preventDefault(); event.stopPropagation();
      if (menuItems.length) selected = (selected + menuItems.length - 1) % menuItems.length;
      paintSelection();
    } else if (['Enter', ' ', 'z', 'Z'].includes(event.key)) {
      event.preventDefault(); event.stopPropagation();
      const item = menuItems[selected];
      if (item && !item.disabled) finishMenu(item.value ?? item.label);
    } else if (event.key === 'Escape' || event.key.toLowerCase() === 'x') {
      event.preventDefault(); event.stopPropagation(); finishMenu(null);
    }
  }
  function menu(title, entries, options = {}) {
    if (!overlay) return Promise.resolve(null);
    if (menuResolve) finishMenu(null);
    if (dialogueResolve) dismissDialogue();
    active = true;
    menuItems = (entries || []).map(entry => typeof entry === 'string' ? { label: entry, value: entry } : entry);
    selected = Math.max(0, Math.min(options.selected || 0, Math.max(0, menuItems.length - 1)));
    const panel = document.createElement('section');
    panel.className = 'menu-window';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-label', String(title || 'Menu'));
    const heading = document.createElement('h2');
    heading.className = 'menu-title';
    setText(heading, title);
    panel.append(heading);
    if (options.description) {
      const description = document.createElement('p');
      description.className = 'menu-description';
      setText(description, options.description);
      panel.append(description);
    }
    const list = document.createElement('div');
    list.className = 'menu-list';
    menuItems.forEach((item, index) => {
      const row = document.createElement('button');
      row.type = 'button';
      row.className = 'menu-option';
      row.dataset.menuIndex = String(index);
      row.disabled = !!item.disabled;
      setText(row, item.label);
      row.addEventListener('click', () => {
        selected = index; paintSelection();
        if (!row.disabled) finishMenu(item.value ?? item.label);
      });
      list.append(row);
    });
    panel.append(list);
    if (options.footer) {
      const footer = document.createElement('small');
      footer.className = 'menu-footer';
      setText(footer, options.footer);
      panel.append(footer);
    }
    overlay.replaceChildren(panel);
    overlay.classList.add('visible');
    paintSelection();
    document.addEventListener('keydown', menuKey, true);
    menuCleanup = () => document.removeEventListener('keydown', menuKey, true);
    return new Promise(resolve => { menuResolve = resolve; });
  }

  function close() {
    if (dialogueResolve) dismissDialogue();
    if (menuResolve) finishMenu(null);
  }
  function updateHud(location, party) {
    const loc = $('#location');
    const partyHud = $('#partyHud');
    if (loc && location != null) setText(loc, location);
    if (partyHud && Array.isArray(party)) {
      partyHud.replaceChildren(...party.map(mon => {
        const chip = document.createElement('span');
        chip.className = 'party-chip';
        setText(chip, `${mon.name || mon.species || 'Pokémon'} · ${Math.max(0, mon.hp ?? 0)}/${mon.maxHp ?? mon.hp ?? 0}`);
        return chip;
      }));
    }
  }
  return { get active() { return active; }, say, menu, close, updateHud };
})();

/* ============================================================
   POKÉMON ECLIPSE — pixel-art sprite factory
   All creatures & characters are drawn procedurally.
   ============================================================ */
'use strict';

function hexToRgb(h) {
  h = h.replace('#','');
  if (h.length === 3) h = h.split('').map(c=>c+c).join('');
  return [parseInt(h.slice(0,2),16), parseInt(h.slice(2,4),16), parseInt(h.slice(4,6),16)];
}
function rgbToHex(r,g,b) { return '#' + [r,g,b].map(v=>clamp(Math.round(v),0,255).toString(16).padStart(2,'0')).join(''); }
function shiftColor(hex, deg, satMul=1, lightMul=1) {
  let [r,g,b] = hexToRgb(hex).map(v=>v/255);
  const max = Math.max(r,g,b), min = Math.min(r,g,b);
  let h=0, s=0, l=(max+min)/2;
  if (max !== min) {
    const d = max-min;
    s = l > .5 ? d/(2-max-min) : d/(max+min);
    h = max===r ? ((g-b)/d+(g<b?6:0)) : max===g ? ((b-r)/d+2) : ((r-g)/d+4);
    h *= 60;
  }
  h = (h + deg + 360) % 360; s = clamp(s*satMul,0,1); l = clamp(l*lightMul,0,1);
  const c = (1-Math.abs(2*l-1))*s, x = c*(1-Math.abs((h/60)%2-1)), m = l-c/2;
  let rr=0,gg=0,bb=0;
  if (h<60){rr=c;gg=x;} else if(h<120){rr=x;gg=c;} else if(h<180){gg=c;bb=x;}
  else if(h<240){gg=x;bb=c;} else if(h<300){rr=x;bb=c;} else {rr=c;bb=x;}
  return rgbToHex((rr+m)*255,(gg+m)*255,(bb+m)*255);
}

const PX = {
  rect(c,x,y,w,h,col){ c.fillStyle=col; c.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h)); },
  ell(c,cx,cy,rx,ry,col){
    c.fillStyle=col;
    for (let y=-Math.ceil(ry); y<=ry; y++){
      const hw = Math.floor(rx*Math.sqrt(Math.max(0,1-(y*y)/(ry*ry))));
      c.fillRect(Math.round(cx-hw), Math.round(cy+y), hw*2+1, 1);
    }
  },
  ring(c,cx,cy,rx,ry,col,w=2){ // outlined ellipse by layered ellipses
    PX.ell(c,cx,cy,rx,ry,col);
    PX.ell(c,cx,cy,rx-w,ry-w,'__clear__');
  },
  tri(c,x1,y1,x2,y2,x3,y3,col){
    c.fillStyle=col;
    const minY=Math.floor(Math.min(y1,y2,y3)), maxY=Math.ceil(Math.max(y1,y2,y3));
    for (let y=minY;y<=maxY;y++){
      const xs=[];
      const edges=[[x1,y1,x2,y2],[x2,y2,x3,y3],[x3,y3,x1,y1]];
      for(const [ax,ay,bx,by] of edges){
        if ((y>=ay&&y<=by)||(y>=by&&y<=ay)){
          if (by===ay) continue;
          xs.push(ax+(bx-ax)*((y-ay)/(by-ay)));
        }
      }
      if (xs.length>=2){ const xa=Math.round(Math.min(...xs)), xb=Math.round(Math.max(...xs)); c.fillRect(xa,y,xb-xa+1,1); }
    }
  },
  line(c,x1,y1,x2,y2,col,w=2){
    const dx=x2-x1, dy=y2-y1; const steps=Math.max(Math.abs(dx),Math.abs(dy),1);
    c.fillStyle=col;
    for(let i=0;i<=steps;i++){ const x=Math.round(x1+dx*i/steps), y=Math.round(y1+dy*i/steps); c.fillRect(x-Math.floor(w/2),y-Math.floor(w/2),w,w); }
  }
};

/* draw an outlined blob: silhouette + fill + shading + highlight */
function blob(c,cx,cy,rx,ry,dark,base,light,opts={}) {
  PX.ell(c,cx,cy,rx+2,ry+2,dark);
  PX.ell(c,cx,cy,rx,ry,base);
  PX.ell(c,cx-1,cy+ry*0.32,rx*0.78,ry*0.48,shiftColor(base,-8,.9,.82));
  if (opts.highlight!==false) PX.ell(c,cx-rx*0.25,cy-ry*0.34,rx*0.52,ry*0.3,light);
  // re-apply lower belly shading edge
  PX.ell(c,cx-rx*0.1,cy+ry*0.58,rx*0.66,ry*0.28,dark);
  PX.ell(c,cx-rx*0.05,cy+ry*0.5,rx*0.6,ry*0.3,shiftColor(base,-4,.85,.9));
}

function eye(c,x,y,rx,ry,opts={}) {
  PX.ell(c,x,y,rx+1,ry+1,'#1a1420');
  PX.ell(c,x,y,rx,ry,'#ffffff');
  PX.ell(c,x+ (opts.look||0.4)*rx*.4,y+ry*.05,rx*.62,ry*.66,opts.iris||'#1f2937');
  PX.ell(c,x-rx*.18,y-ry*.26,rx*.28,ry*.28,'#ffffff');
  if (opts.pupilShine!==false) PX.ell(c,x+rx*.25,y+ry*.2,rx*.12,ry*.14,'#ffffff');
}

function mouth(c,x,y,w,h,col='#2a1a24') { PX.ell(c,x,y,w,h,col); }

function makeCreatureCanvas(sp, opts={}) {
  const S = 72;
  const c = document.createElement('canvas'); c.width=S; c.height=S;
  const x = c.getContext('2d'); x.imageSmoothingEnabled=false;
  const shiny = !!opts.shiny;
  let [base,dark,light,accent,extra] = sp.cols;
  if (shiny) {
    base = shiftColor(base, 55, 1.15, 1.05);
    dark = shiftColor(dark, 55, 1.1, .9);
    light = shiftColor(light, 50, 1.1, 1.02);
    accent = shiftColor(accent, 125, 1.2, 1.05);
    extra = shiftColor(extra, 125, 1.1, 1.02);
  }
  const C = {base,dark,light,accent,extra,shiny};
  x.save();
  const scale = sp.scale || 1;
  x.translate(S/2, S/2); x.scale(scale,scale); x.translate(-S/2,-S/2);

  const shape = sp.shape || 'quad';
  const f = new Set(sp.features||[]);

  // --- shared feature helpers ---
  const wings = (cx,cy,span,drop,wingCol,edgeCol) => {
    PX.tri(x,cx,cy,cx-span,cy-drop,cx-span*.35,cy+drop*.9,edgeCol);
    PX.tri(x,cx,cy,cx-span*.92,cy-drop*.85,cx-span*.3,cy+drop*.55,wingCol);
    PX.tri(x,cx,cy,cx+span,cy-drop,cx+span*.35,cy+drop*.9,edgeCol);
    PX.tri(x,cx,cy,cx+span*.92,cy-drop*.85,cx+span*.3,cy+drop*.55,wingCol);
  };
  const horns = (cx,cy,spread,len,col=accent) => {
    PX.tri(x,cx-spread,cy,cx-spread*.5,cy-len,cx-spread*.15,cy,col);
    PX.tri(x,cx+spread,cy,cx+spread*.5,cy-len,cx+spread*.15,cy,col);
  };
  const flame = (cx,cy,size,col=accent,hi=extra) => {
    PX.ell(x,cx,cy+size*.3,size*.55,size*.5,col);
    PX.tri(x,cx-size*.55,cy+size*.2,cx,cy-size*.9,cx+size*.55,cy+size*.2,col);
    PX.tri(x,cx-size*.3,cy+size*.1,cx,cy-size*.5,cx+size*.25,cy+size*.1,hi);
    PX.ell(x,cx,cy+size*.32,size*.34,size*.26,hi);
  };
  const leaf = (cx,cy,w,h,rot=0,col=accent,vein=dark) => {
    // pixel leaf: pointed oval
    PX.ell(x,cx,cy,w,h,col);
    PX.tri(x,cx-w,cy,cx,cy-h*1.4,cx+w,cy,col);
    PX.line(x,cx,cy+h*.6,cx,cy-h*.8,vein,1);
  };
  const crystal = (cx,cy,w,h,col=accent,hi=extra) => {
    PX.tri(x,cx,cy-h,cx-w,cy+h*.15,cx+w,cy+h*.15,col);
    PX.tri(x,cx-w*.3,cy-h*.65,cx-w*.1,cy+h*.15,cx+w*.2,cy+h*.15,hi);
  };
  const eyeSet = (cx,cy,gap,rx=3,ry=4) => { eye(x,cx-gap,cy,rx,ry); eye(x,cx+gap,cy,rx,ry); };

  if (shape === 'quad') {
    // tail
    if (f.has('tail')||f.has('tailflame')) {
      PX.line(x,30,46,15,38,dark,7); PX.line(x,30,46,15,38,base,4);
      PX.ell(x,14,37,5,4,base); PX.ell(x,14,37,2,2,light);
      if (f.has('tailflame')) flame(12,30,7,accent,extra);
    }
    // legs
    PX.rect(x,29,46,7,12,dark); PX.rect(x,40,46,7,12,dark);
    PX.rect(x,30,46,5,11,base); PX.rect(x,41,46,5,11,base);
    PX.rect(x,30,55,6,3,dark); PX.rect(x,41,55,6,3,dark);
    if (f.has('claws')) { PX.rect(x,28,57,3,2,extra); PX.rect(x,45,57,3,2,extra); }
    // body
    blob(x,40,39,19,12,dark,base,light);
    // markings
    if (f.has('magma')) { PX.ell(x,32,39,5,3,accent); PX.ell(x,42,37,3,2,accent); }
    // head
    blob(x,55,27,14,12,dark,base,light);
    // snout
    if (f.has('snout')) { PX.ell(x,64,31,8,5,dark); PX.ell(x,64,30,7,4,base); PX.ell(x,64,29,3,1.5,light); }
    else { PX.ell(x,62,31,6,4,dark); PX.ell(x,62,30,5,3,base); }
    // ears
    if (f.has('ears')) {
      PX.tri(x,47,17,50,5,56,15,dark); PX.tri(x,48,16,51,8,55,15,base);
      PX.tri(x,65,16,62,4,70,14,dark); PX.tri(x,65,16,63,7,69,14,base);
      if (f.has('tailflame')) { PX.tri(x,50,14,51,8,54,14,accent); PX.tri(x,64,13,63,7,68,13,accent); }
    }
    if (f.has('mane')) { PX.ell(x,46,23,12,7,accent); PX.ell(x,46,23,9,4,light); }
    if (f.has('spikes')) { for(let i=0;i<3;i++) PX.tri(x,30+i*8,31,34+i*8,22,37+i*8,31,accent); }
    eyeSet(58,25,6,3,4);
    if (f.has('glasses')) { PX.rect(x,50,23,8,1,extra); PX.rect(x,64,23,8,1,extra); PX.rect(x,58,23,7,1,extra); }
    PX.ell(x,64,34,3,1.5,dark);
    if (f.has('claws')) { PX.rect(x,68,33,3,1,extra); }
  }

  else if (shape === 'biped' || shape === 'lizard') {
    // tail for lizard/biped
    if (f.has('tail')||f.has('tailflame')) {
      PX.line(x,30,47,14,41,dark,7); PX.line(x,30,47,14,41,base,4);
      if (f.has('blades')) { PX.tri(x,18,44,10,33,26,39,accent); PX.tri(x,20,44,14,36,26,41,light); }
      if (f.has('tailflame')) flame(12,34,7,accent,extra);
    }
    // legs
    PX.rect(x,28,47,8,13,dark); PX.rect(x,40,47,8,13,dark);
    PX.rect(x,29,47,6,12,base); PX.rect(x,41,47,6,12,base);
    PX.rect(x,27,58,8,3,dark); PX.rect(x,40,58,8,3,dark);
    // body
    blob(x,38,41,14,13,dark,base,light);
    // arms
    PX.line(x,28,36,20,46,dark,5); PX.line(x,28,36,20,46,base,3);
    PX.line(x,48,36,56,47,dark,5); PX.line(x,48,36,56,47,base,3);
    if (f.has('claws')) { PX.rect(x,17,45,4,2,extra); PX.rect(x,54,46,4,2,extra); }
    // neck + head
    blob(x,50,26,13,11,dark,base,light);
    // crest / fin / leaf
    if (f.has('fin')) { PX.tri(x,48,17,55,4,60,18,accent); PX.tri(x,50,17,55,8,58,18,light); }
    if (f.has('crest')) { PX.tri(x,44,15,47,3,53,14,accent); PX.tri(x,52,14,57,3,60,16,accent); }
    if (f.has('leaf')) { leaf(50,12,7,9,0,accent,light); leaf(58,16,5,7,.3,shiftColor(accent,20,.9,.9),light); }
    if (f.has('horn')) { PX.tri(x,58,16,62,8,66,18,accent); }
    if (f.has('blades')) { PX.tri(x,34,29,24,20,36,22,accent); PX.tri(x,36,28,28,23,37,24,light); }
    if (f.has('aura')) { PX.ell(x,50,36,10,4,'rgba(141,224,255,.35)'); }
    eyeSet(52,25,5,3,4);
    if (f.has('visor')) { PX.rect(x,43,21,17,4,'#0b1a2a'); PX.rect(x,44,22,7,2,accent); }
    if (f.has('mask')) { PX.ell(x,57,31,8,5,dark); PX.ell(x,57,30,6,3,light); }
    if (f.has('belt')) { PX.rect(x,26,47,25,4,dark); PX.rect(x,36,47,6,5,accent); }
    if (f.has('cloak')) { PX.tri(x,24,26,18,58,46,52,'rgba(120,220,230,.55)'); PX.tri(x,26,30,22,54,38,50,accent); }
    if (f.has('magma')) { PX.ell(x,33,42,5,3,accent); PX.rect(x,34,45,2,7,accent); }
    PX.ell(x,58,32,3,1.5,dark);
  }

  else if (shape === 'bird') {
    // tail feathers
    PX.tri(x,28,44,8,52,26,33,dark); PX.tri(x,28,42,12,48,28,31,base);
    PX.tri(x,27,39,7,38,25,29,accent); PX.tri(x,27,40,10,41,24,32,light);
    // wings
    if (f.has('wings')) {
      PX.tri(x,32,33,10,28,20,52,dark); PX.tri(x,32,34,15,31,22,49,base);
      PX.tri(x,40,34,56,24,48,54,dark); PX.tri(x,40,35,51,28,46,50,base);
      PX.line(x,16,33,24,48,dark,1); PX.line(x,49,29,45,48,dark,1);
    }
    if (f.has('fluff')) { PX.ell(x,33,36,13,10,light); PX.ell(x,33,36,11,8,'#ffffff'); }
    PX.rect(x,32,54,4,6,dark); PX.rect(x,41,54,4,6,dark);
    PX.rect(x,30,59,7,2,dark); PX.rect(x,41,59,7,2,dark);
    blob(x,38,40,16,14,dark,base,light);
    blob(x,52,25,11,10,dark,base,light);
    // beak
    PX.tri(x,61,24,68,27,61,30,accent); PX.tri(x,62,26,67,27,62,29,extra);
    // crest
    if (f.has('crest')) { PX.tri(x,46,16,50,4,55,16,accent); PX.tri(x,54,15,59,5,61,18,accent); }
    if (f.has('mask')) { PX.rect(x,45,19,15,4,dark); PX.rect(x,46,20,6,2,accent); }
    eye(x,52,23,3,4);
    if (f.has('ears')) { PX.tri(x,42,19,38,8,47,17,dark); PX.tri(x,43,18,40,11,46,17,base); PX.tri(x,56,18,60,7,63,19,dark); }
    // feet talons
    if (f.has('claws')) { PX.rect(x,29,61,3,2,extra); PX.rect(x,44,61,3,2,extra); }
  }

  else if (shape === 'bug') {
    // legs
    for (let i=0;i<3;i++){ PX.line(x,28+i*2,44+i*3,18+i*3,52+i*3,dark,2); PX.line(x,47-i*1,44+i*3,57-i*2,52+i*3,dark,2); }
    // wings
    if (f.has('wings')) {
      PX.tri(x,36,24,4,18,14,52,dark); PX.tri(x,35,25,9,21,17,48,base);
      PX.tri(x,40,24,68,16,60,52,dark); PX.tri(x,40,25,63,20,56,48,base);
      PX.rect(x,12,28,4,1,'rgba(255,255,255,.55)'); PX.rect(x,56,27,5,1,'rgba(255,255,255,.55)');
    }
    // body segments
    blob(x,36,41,12,13,dark,base,light);
    PX.ell(x,24,48,8,7,dark); PX.ell(x,24,47,7,6,base);
    PX.ell(x,46,47,8,7,dark); PX.ell(x,46,47,7,6,base);
    // bubble / fluff
    if (f.has('bubble')) { PX.ell(x,36,17,12,10,'#bfefff'); PX.ell(x,33,14,5,4,'#ffffff'); PX.ell(x,41,20,3,2,'rgba(255,255,255,.7)'); }
    if (f.has('fluff')) { PX.ell(x,36,28,15,9,light); PX.ell(x,36,28,12,7,'#ffffff'); }
    // head
    blob(x,52,33,11,9,dark,base,light);
    // antennae / horns
    PX.line(x,48,24,42,10,accent,2); PX.ell(x,41,9,2,2,extra);
    PX.line(x,56,24,61,10,accent,2); PX.ell(x,62,9,2,2,extra);
    if (f.has('horn')) { PX.tri(x,54,22,60,14,64,24,accent); }
    eye(x,50,31,3,4); eye(x,58,31,3,4);
    if (f.has('eyes')) { eye(x,48,31,2,3); eye(x,57,31,2,3); }
    PX.ell(x,58,38,2,1,dark);
    if (f.has('spikes')) { PX.tri(x,26,35,30,27,34,35,accent); }
  }

  else if (shape === 'serpent') {
    // coil
    PX.ell(x,37,53,23,9,dark); PX.ell(x,37,52,21,7,base); PX.ell(x,37,49,15,5,shiftColor(base,8,.9,.9));
    PX.ell(x,35,46,16,7,dark); PX.ell(x,35,45,14,5,base);
    // neck
    PX.line(x,44,44,50,25,dark,10); PX.line(x,44,44,50,25,base,6);
    // head
    blob(x,53,22,12,10,dark,base,light);
    if (f.has('whiskers')) { PX.line(x,59,27,66,30,accent,1); PX.line(x,58,31,65,35,accent,1); }
    if (f.has('fins')) { PX.tri(x,48,14,53,4,58,15,accent); PX.tri(x,56,15,62,6,64,18,accent); }
    if (f.has('horns')) { PX.tri(x,44,15,41,5,49,14,accent); PX.tri(x,60,14,65,4,68,16,accent); }
    if (f.has('scales')) { for(let i=0;i<4;i++) PX.ell(x,24+i*8,49,2,1,light); }
    eyeSet(51,21,4,3,4);
    PX.ell(x,61,28,3,1.5,dark);
    if (f.has('wings')) { PX.tri(x,38,24,24,12,30,38,dark); PX.tri(x,38,26,28,17,32,36,accent); }
  }

  else if (shape === 'blob') {
    if (f.has('roots')) { PX.line(x,28,54,22,62,dark,3); PX.line(x,44,54,50,62,dark,3); }
    if (f.has('wings')) { PX.tri(x,34,30,16,22,22,44,accent); PX.tri(x,44,30,62,22,56,44,accent); }
    blob(x,36,39,19,17,dark,base,light);
    if (f.has('shell')) { PX.ell(x,36,45,15,11,light); PX.ell(x,36,45,13,9,'#ffffff'); PX.tri(x,30,44,36,37,42,44,accent); }
    if (f.has('hood')) { PX.ell(x,36,26,16,13,accent); PX.ell(x,36,30,12,10,base); }
    if (f.has('leaves')) { leaf(30,20,7,9,-.4,accent,light); leaf(42,18,7,9,.3,accent,light); leaf(36,15,6,8,0,shiftColor(accent,20,.9,1.05),light); }
    if (f.has('flower')) { PX.ell(x,36,10,9,5,accent); PX.ell(x,36,10,5,2.5,extra); PX.ell(x,36,10,2,1,dark); }
    if (f.has('dress')) { PX.tri(x,24,42,36,60,48,42,light); PX.tri(x,27,44,36,58,45,44,accent); }
    if (f.has('ears')) { PX.tri(x,26,25,22,10,34,22,dark); PX.tri(x,46,25,50,10,56,22,dark); }
    if (f.has('horn')) { PX.tri(x,36,22,38,8,42,23,accent); }
    eyeSet(36,34,6,3,4);
    PX.ell(x,36,43,3,1.5,dark);
    if (f.has('eyes')) { eye(x,33,35,2,3); eye(x,41,35,2,3); }
    // feet
    PX.ell(x,28,55,5,3,dark); PX.ell(x,44,55,5,3,dark);
  }

  else if (shape === 'ghost') {
    if (f.has('gas')) { PX.ell(x,36,38,23,18,'rgba(120,80,160,.45)'); PX.ell(x,25,52,9,6,'rgba(120,80,160,.4)'); PX.ell(x,49,53,10,6,'rgba(120,80,160,.4)'); }
    // wispy bottom
    PX.tri(x,18,44,24,60,30,42,base); PX.tri(x,28,44,37,63,44,42,base); PX.tri(x,42,44,50,60,55,40,base);
    PX.ell(x,36,40,19,16,dark); PX.ell(x,36,39,17,14,base);
    PX.ell(x,32,34,10,6,light);
    if (f.has('flame')) { flame(36,14,10,accent,extra); PX.rect(x,34,22,4,8,light); }
    if (f.has('wax')) { PX.rect(x,30,27,12,14,light); PX.ell(x,36,27,6,3,extra); }
    if (f.has('chandelier')) { PX.rect(x,18,35,36,3,dark); PX.ell(x,20,36,3,4,light); PX.ell(x,52,36,3,4,light); PX.line(x,36,26,36,16,accent,3); }
    if (f.has('rag')) { PX.ell(x,36,34,17,14,base); PX.ell(x,36,30,13,9,light); PX.rect(x,22,38,28,8,base); PX.tri(x,20,42,26,54,32,42,base); PX.tri(x,40,42,46,54,52,42,base); PX.rect(x,29,20,6,3,dark); PX.rect(x,39,20,6,3,dark); eye(x,34,30,2,3,'#1a1420'); eye(x,44,30,2,3,'#1a1420'); }
    if (f.has('arms')) { PX.line(x,19,36,10,46,base,4); PX.line(x,53,36,62,46,base,4); }
    if (f.has('spikes')) { for(let i=0;i<4;i++) PX.tri(x,20+i*10,24,24+i*10,14,28+i*10,24,accent); }
    eyeSet(36,32,6,3,4);
    PX.ell(x,36,42,4,2,dark);
    if (f.has('eyes')) { eye(x,32,33,2,3); eye(x,41,33,2,3); }
  }

  else if (shape === 'fish') {
    PX.tri(x,18,40,2,28,10,46,dark); PX.tri(x,18,40,5,31,12,45,accent);
    PX.ell(x,38,38,19,14,dark); PX.ell(x,38,38,17,12,base);
    PX.ell(x,32,33,10,5,light);
    if (f.has('fins')) { PX.tri(x,36,22,44,10,50,24,accent); PX.tri(x,50,36,62,30,58,46,accent); }
    if (f.has('whiskers')) { PX.line(x,54,40,62,48,accent,1); PX.line(x,54,34,62,28,accent,1); }
    if (f.has('scales')) { for(let i=0;i<5;i++) PX.ell(x,28+i*5,38+((i%2)*2),1,1,light); }
    eye(x,48,34,3,4);
    PX.ell(x,54,43,3,1.5,dark);
  }

  else if (shape === 'armor') {
    // legs / base
    if (f.has('legs')) { PX.line(x,24,45,18,58,dark,5); PX.line(x,48,45,54,58,dark,5); PX.line(x,24,45,18,58,base,3); PX.line(x,48,45,54,58,base,3); }
    // shield
    if (f.has('shield')) {
      PX.tri(x,18,25,30,16,34,52,dark); PX.tri(x,20,27,29,19,32,49,base);
      PX.tri(x,20,27,28,22,29,40,light);
      PX.rect(x,24,36,4,2,accent);
    }
    // main body
    PX.rect(x,32,22,20,28,dark); PX.rect(x,34,24,16,24,base); PX.rect(x,35,25,7,7,light);
    if (f.has('cross')) { PX.rect(x,26,34,34,6,dark); PX.rect(x,28,35,30,4,base); }
    if (f.has('core')) { PX.ell(x,41,41,4,4,accent); PX.ell(x,41,41,2,2,extra); }
    // head / crown
    blob(x,44,20,10,8,dark,base,light);
    if (f.has('crown')) { PX.rect(x,34,10,20,3,accent); PX.tri(x,35,11,38,4,41,11,accent); PX.tri(x,42,11,45,3,48,11,accent); PX.tri(x,49,11,52,5,54,11,accent); }
    if (f.has('horn')) { PX.tri(x,52,15,58,8,58,20,accent); }
    // sword
    if (f.has('sword')) { PX.rect(x,56,18,3,28,light); PX.rect(x,55,18,5,2,accent); PX.rect(x,56,30,3,14,extra); }
    eyeSet(44,20,4,2,3);
    if (f.has('eyes')) { eye(x,42,20,2,3); eye(x,48,20,2,3); }
    if (f.has('wings')) { PX.tri(x,34,30,18,20,26,44,dark); PX.tri(x,34,31,22,24,28,42,accent); }
  }

  else if (shape === 'dragon') {
    // tail
    PX.line(x,24,48,8,52,dark,8); PX.line(x,24,48,8,52,base,5);
    PX.tri(x,9,52,2,44,8,58,dark); PX.tri(x,10,52,4,47,9,57,accent);
    // wings
    if (f.has('wings')) {
      PX.tri(x,38,30,8,10,20,50,dark); PX.tri(x,38,32,13,15,23,47,base);
      PX.tri(x,42,28,70,8,58,52,dark); PX.tri(x,42,30,65,13,55,48,base);
      PX.line(x,18,17,23,44,accent,1); PX.line(x,62,17,56,44,accent,1);
    }
    // legs
    PX.rect(x,26,47,9,15,dark); PX.rect(x,42,47,9,15,dark);
    PX.rect(x,27,47,7,14,base); PX.rect(x,43,47,7,14,base);
    PX.rect(x,24,61,9,3,dark); PX.rect(x,42,61,9,3,dark);
    if (f.has('claws')) { PX.rect(x,23,62,3,2,extra); PX.rect(x,46,62,3,2,extra); }
    // body + neck + head
    blob(x,39,42,16,14,dark,base,light);
    PX.line(x,46,34,51,21,dark,11); PX.line(x,46,34,51,21,base,7);
    blob(x,54,19,12,10,dark,base,light);
    // horns / crest
    if (f.has('horns')) { PX.tri(x,46,12,40,2,50,11,accent); PX.tri(x,57,11,62,1,66,13,accent); }
    if (f.has('crest')) { PX.tri(x,46,13,51,2,56,13,accent); }
    if (f.has('halo')) { PX.ell(x,54,5,13,3,'rgba(255,209,102,.65)'); PX.ell(x,54,5,11,2,'#fff8e0'); }
    if (f.has('armor')) { PX.rect(x,30,34,22,6,accent); PX.rect(x,33,36,6,4,extra); PX.rect(x,44,36,6,4,extra); }
    if (f.has('core')) { PX.ell(x,40,43,5,5,dark); PX.ell(x,40,43,3.5,3.5,accent); PX.ell(x,40,42,1.5,1.5,extra); }
    if (f.has('fins')) { PX.tri(x,38,30,32,16,44,26,accent); }
    if (f.has('spikes')) { for(let i=0;i<4;i++) PX.tri(x,28+i*5,30,30+i*5,20,33+i*5,30,accent); }
    if (f.has('crown')) { PX.rect(x,45,8,20,3,accent); PX.tri(x,47,9,50,2,53,9,accent); PX.tri(x,55,9,58,1,61,9,accent); }
    eyeSet(54,18,5,3,4);
    PX.ell(x,63,24,3,1.5,dark);
    if (f.has('mask')) { PX.ticks = 1; PX.rect(x,47,14,16,4,dark); PX.rect(x,48,15,6,2,accent); }
  }

  else { // generic blob fallback
    blob(x,36,36,18,18,dark,base,light);
    eyeSet(36,34,7,3,4);
  }

  // shiny sparkles in sprite corner
  if (shiny) {
    const spark = (sx,sy) => { PX.rect(x,sx-3,sy,7,1,'#fff7b0'); PX.rect(x,sx,sy-3,1,7,'#fff7b0'); PX.rect(x,sx-1,sy-1,3,3,'#ffffff'); };
    spark(60,10); spark(12,18);
  }
  x.restore();
  return c;
}

const CREATURE_CACHE = new Map();
function creatureCanvas(id, shiny = false, key = '') {
  const k = id + '|' + (shiny?'s':'n') + '|' + key;
  if (CREATURE_CACHE.has(k)) return CREATURE_CACHE.get(k);
  const sp = SPECIES[id];
  if (!sp) return null;
  const c = makeCreatureCanvas(sp, { shiny });
  CREATURE_CACHE.set(k, c);
  return c;
}
function drawCreature(ctx, id, x, y, size, opts = {}) {
  const sp = SPECIES[id];
  if (!sp) return;
  const c = creatureCanvas(id, opts.shiny || false, opts.cacheKey || '');
  if (!c) return;
  ctx.save();
  ctx.imageSmoothingEnabled = false;
  if (opts.flip) { ctx.translate(x + size/2, 0); ctx.scale(-1,1); ctx.translate(-(x + size/2),0); }
  if (opts.alpha != null) ctx.globalAlpha = opts.alpha;
  ctx.drawImage(c, x, y, size, size);
  ctx.restore();
}

@font-face {
  font-family: 'PixelTitle';
  src: url('assets/fonts/PressStart2P.ttf') format('truetype');
  font-display: swap;
}
@font-face {
  font-family: 'PixelBody';
  src: url('assets/fonts/VT323.ttf') format('truetype');
  font-display: swap;
}

:root {
  --ink: #0a0b16;
  --panel: #101528;
  --panel2: #161d38;
  --gold: #f5c542;
  --gold2: #b8862b;
  --cyan: #67e8f9;
  --violet: #9b7bff;
  --rose: #ff7aa8;
  --text: #f4f1e8;
  --muted: #a9b2cf;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #06070d;
  color: var(--text);
  font-family: 'PixelBody', 'Courier New', monospace;
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(1100px 700px at 50% -10%, #1c2450 0%, transparent 60%),
    radial-gradient(900px 600px at 10% 110%, #2a0f2e 0%, transparent 60%),
    radial-gradient(900px 600px at 95% 100%, #062b33 0%, transparent 55%),
    #05060b;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(1px 1px at 20% 30%, rgba(255,255,255,.5) 50%, transparent 51%),
    radial-gradient(1px 1px at 70% 20%, rgba(255,255,255,.35) 50%, transparent 51%),
    radial-gradient(1px 1px at 40% 75%, rgba(255,255,255,.25) 50%, transparent 51%),
    radial-gradient(1px 1px at 85% 65%, rgba(255,255,255,.35) 50%, transparent 51%);
  background-size: 280px 280px, 340px 340px, 400px 400px, 310px 310px;
  opacity: .45;
}

#app {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 10px;
  max-height: 100vh;
}

#gameframe {
  position: relative;
  width: min(96vw, calc((100vh - 58px) * 1.3333), 1100px);
  aspect-ratio: 4 / 3;
  border-radius: 14px;
  background: #06070d;
  overflow: hidden;
  box-shadow:
    0 0 0 3px #1b2444,
    0 0 0 6px #070912,
    0 0 0 8px #2c3766,
    0 18px 60px rgba(0,0,0,.8),
    0 0 90px rgba(103,232,249,.08);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: #0a0f1e;
}

#hint {
  font-family: 'PixelTitle', monospace;
  font-size: 8px;
  letter-spacing: .5px;
  color: #56608a;
  text-align: center;
  line-height: 1.8;
  text-shadow: 0 1px 0 #000;
}

.hud-chip {
  font-family: 'PixelTitle', monospace;
  font-size: 9px;
  letter-spacing: .3px;
  color: #eaf6ff;
  background: linear-gradient(180deg, rgba(16,21,40,.92), rgba(10,13,26,.94));
  border: 2px solid #3b4a80;
  border-radius: 7px;
  padding: 8px 10px 7px;
  box-shadow: 0 3px 0 #05060c, inset 0 0 0 1px rgba(255,255,255,.04);
  text-shadow: 0 2px 0 #000;
}

#hud {
  position: absolute;
  top: 12px;
  left: 12px;
  right: 12px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  pointer-events: none;
  z-index: 4;
  opacity: 0;
  transition: opacity .3s;
}
#hud.visible { opacity: 1; }
#hud .hud-chip { pointer-events: none; }
#partyHud { display: flex; gap: 7px; align-items: center; }
.pip {
  width: 11px; height: 11px; border-radius: 50%;
  background: #3ddc84;
  box-shadow: 0 0 0 2px #0a0f1e, 0 0 8px rgba(61,220,132,.6);
}
.pip.hurt { background: #f5c542; box-shadow: 0 0 0 2px #0a0f1e, 0 0 8px rgba(245,197,66,.6); }
.pip.bad { background: #ef4444; box-shadow: 0 0 0 2px #0a0f1e, 0 0 8px rgba(239,68,68,.6); }
.pip.faint { background: #4b5563; box-shadow: 0 0 0 2px #0a0f1e; }

/* ---------- dialogue ---------- */
#dialogue {
  position: absolute;
  left: 14px; right: 14px; bottom: 12px;
  height: 126px;
  z-index: 9;
  background:
    linear-gradient(180deg, rgba(30,39,74,.98), rgba(12,16,32,.99));
  border: 3px solid #e8d9a0;
  border-radius: 12px;
  box-shadow: 0 0 0 3px #141a33, 0 8px 0 rgba(0,0,0,.55), inset 0 0 0 2px #2e3a68, inset 0 0 40px rgba(103,232,249,.05);
  padding: 9px 20px 10px;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  transition: opacity .18s, transform .18s;
}
#dialogue.hidden { opacity: 0; transform: translateY(10px); pointer-events: none; }
#dlgName {
  font-family: 'PixelTitle', monospace;
  font-size: 10px;
  color: var(--gold);
  text-shadow: 0 2px 0 #000;
  min-height: 16px;
  letter-spacing: .5px;
  margin-bottom: 4px;
}
#dlgName:empty { display: none; }
#dlgText {
  font-family: 'PixelBody', monospace;
  font-size: 27px;
  line-height: 1.08;
  color: #f7f4e9;
  text-shadow: 0 2px 0 #05060c;
  flex: 1;
  white-space: pre-wrap;
  letter-spacing: .3px;
}
#dlgArrow {
  position: absolute;
  right: 20px; bottom: 8px;
  color: var(--gold);
  font-size: 16px;
  animation: bob .7s infinite alternate;
  text-shadow: 0 2px 0 #000;
}
#dlgArrow.hidden { display: none; }
@keyframes bob { from { transform: translateY(0); } to { transform: translateY(-4px); } }

/* ---------- overlay ---------- */
#overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
}
#overlay > * { pointer-events: auto; }
#overlay.hidden { display: none; }

/* ---------- title ---------- */
.title-wrap {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}
.title-logo {
  text-align: center;
  pointer-events: none;
  margin-top: -60px;
  animation: floaty 6s ease-in-out infinite;
}
.title-kicker {
  font-family: 'PixelTitle', monospace;
  font-size: 12px;
  color: var(--cyan);
  letter-spacing: 6px;
  text-shadow: 0 0 18px rgba(103,232,249,.7), 0 3px 0 #000;
  margin-bottom: 16px;
}
.title-main {
  font-family: 'PixelTitle', monospace;
  font-size: clamp(30px, 6.2vw, 66px);
  line-height: 1.08;
  color: #fff;
  text-shadow:
    0 0 26px rgba(155,123,255,.8),
    0 6px 0 #2b1a5c,
    0 9px 0 #0a0b16,
    0 12px 30px rgba(0,0,0,.9);
  letter-spacing: 2px;
}
.title-main .g {
  color: var(--gold);
  text-shadow: 0 0 26px rgba(245,197,66,.7), 0 6px 0 #6b3e0a, 0 9px 0 #0a0b16;
}
.title-sub {
  font-family: 'PixelTitle', monospace;
  font-size: clamp(8px, 1.2vw, 13px);
  color: #d9d2ff;
  letter-spacing: 4px;
  margin-top: 20px;
  text-shadow: 0 2px 0 #000;
}
@keyframes floaty { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }

.title-menu {
  position: absolute;
  bottom: 8%;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: min(360px, 70%);
}
.title-menu .pbtn { width: 100%; }

.title-foot {
  position: absolute;
  bottom: 18px;
  width: 100%;
  text-align: center;
  font-family: 'PixelTitle', monospace;
  font-size: 8px;
  color: #59648e;
  letter-spacing: 1px;
  text-shadow: 0 2px 0 #000;
}

/* ---------- buttons ---------- */
.pbtn {
  font-family: 'PixelTitle', monospace;
  font-size: 10px;
  letter-spacing: 1px;
  color: #fdfbf3;
  background: linear-gradient(180deg, #2a3568 0%, #1a2247 60%, #131a38 100%);
  border: 2px solid #7e8bc4;
  border-radius: 9px;
  padding: 13px 18px 12px;
  box-shadow: 0 4px 0 #060811, inset 0 1px 0 rgba(255,255,255,.16);
  cursor: pointer;
  transition: transform .08s, box-shadow .08s, filter .12s;
  text-shadow: 0 2px 0 #000;
  position: relative;
}
.pbtn:hover { filter: brightness(1.18); transform: translateY(-1px); }
.pbtn:active { transform: translateY(3px); box-shadow: 0 1px 0 #060811, inset 0 1px 0 rgba(255,255,255,.1); }
.pbtn.gold {
  color: #241802;
  background: linear-gradient(180deg, #ffe89a 0%, #f5c542 55%, #d99b1e 100%);
  border-color: #fff0b8;
  text-shadow: 0 1px 0 rgba(255,255,255,.5);
  box-shadow: 0 4px 0 #6b3e0a, inset 0 1px 0 rgba(255,255,255,.5);
}
.pbtn.gold:active { box-shadow: 0 1px 0 #6b3e0a; }
.pbtn.small { font-size: 8px; padding: 9px 12px 8px; }
.pbtn.danger { border-color: #b45a6a; background: linear-gradient(180deg,#4a2230,#2a1018); }
.pbtn:disabled { filter: grayscale(.7) brightness(.7); cursor: not-allowed; transform: none; }

/* ---------- generic panel ---------- */
.screen {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(800px 500px at 50% 0%, rgba(64,84,160,.28), transparent 65%),
    linear-gradient(180deg, rgba(8,11,24,.96), rgba(5,7,14,.985));
  display: flex;
  flex-direction: column;
  padding: 26px 30px 20px;
  z-index: 21;
}
.screen-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  border-bottom: 2px solid #2a3560;
  padding-bottom: 12px;
}
.screen-title {
  font-family: 'PixelTitle', monospace;
  font-size: 20px;
  color: var(--gold);
  text-shadow: 0 3px 0 #000;
  letter-spacing: 1px;
}
.screen-sub { color: var(--muted); font-size: 23px; line-height: 1; margin-top: 8px; }
.screen-body { flex: 1; overflow: auto; min-height: 0; }
.screen-foot { display: flex; gap: 10px; justify-content: flex-end; padding-top: 14px; }
.xbtn {
  font-family: 'PixelTitle', monospace;
  font-size: 9px;
  color: #d8def5;
  background: #1a2244;
  border: 2px solid #3c4a7d;
  border-radius: 8px;
  padding: 10px 12px;
  cursor: pointer;
}
.xbtn:hover { background: #253061; }

/* ---------- battle UI ---------- */
.battle-ui {
  position: absolute;
  left: 14px; right: 14px; bottom: 12px;
  height: 126px;
  z-index: 10;
  display: flex;
  gap: 10px;
}
.battle-text {
  flex: 1;
  background: linear-gradient(180deg, rgba(30,39,74,.98), rgba(12,16,32,.99));
  border: 3px solid #e8d9a0;
  border-radius: 12px;
  box-shadow: 0 0 0 3px #141a33, 0 8px 0 rgba(0,0,0,.55), inset 0 0 0 2px #2e3a68;
  padding: 12px 18px;
  display: flex;
  align-items: center;
  font-size: 27px;
  line-height: 1.1;
  color: #f7f4e9;
  text-shadow: 0 2px 0 #000;
}
.battle-cmd {
  width: 330px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 7px;
}
.battle-cmd .pbtn { font-size: 9px; padding: 0 8px; display: flex; align-items: center; justify-content: center; }
.battle-cmd .pbtn .key { color: #8fa1d8; font-size: 8px; margin-left: 6px; }

.moves {
  position: absolute;
  left: 14px; right: 14px; bottom: 12px;
  height: 126px;
  z-index: 10;
  display: flex;
  gap: 10px;
}
.move-grid { flex: 1; display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr; gap: 7px; }
.move-btn {
  text-align: left;
  justify-content: flex-start;
  padding: 0 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.move-btn .mname { font-size: 9px; }
.move-btn .mmeta { font-family: 'PixelBody'; font-size: 19px; color: #b9c4e8; letter-spacing: .5px; line-height: 1; }
.move-btn .mtype {
  font-family: 'PixelTitle'; font-size: 7px; padding: 3px 6px 2px; border-radius: 5px; color: #080a14;
  background: #cbd5e1; display: inline-block;
}
.move-btn .row { display: flex; align-items: center; gap: 8px; }

/* ---------- lists / cards ---------- */
.party-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.party-card {
  display: flex;
  gap: 12px;
  background: linear-gradient(180deg, #182044, #10162e);
  border: 2px solid #35437a;
  border-radius: 12px;
  padding: 10px 12px;
  cursor: pointer;
  position: relative;
  transition: border-color .12s, transform .12s;
}
.party-card:hover { border-color: #6f86d6; transform: translateY(-1px); }
.party-card.active { border-color: var(--gold); box-shadow: 0 0 0 2px rgba(245,197,66,.25); }
.party-card.fainted { opacity: .55; }
.pc-sprite { width: 74px; height: 74px; flex: 0 0 74px; image-rendering: pixelated; align-self: center; }
.pc-info { flex: 1; min-width: 0; }
.pc-top { display: flex; justify-content: space-between; align-items: baseline; gap: 6px; }
.pc-name { font-family: 'PixelTitle'; font-size: 9px; color: #fff; text-shadow: 0 2px 0 #000; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.pc-lv { font-family: 'PixelTitle'; font-size: 8px; color: var(--gold); }
.pc-types { display: flex; gap: 5px; margin: 6px 0 5px; }
.tchip { font-family: 'PixelTitle'; font-size: 6px; padding: 3px 5px 2px; border-radius: 4px; color: #05060c; letter-spacing: .3px; }
.pc-hp { font-family: 'PixelBody'; font-size: 17px; color: #cdd6f4; display: flex; justify-content: space-between; }
.bar { height: 7px; background: #05070f; border-radius: 4px; overflow: hidden; border: 1px solid #2b3560; }
.bar > i { display: block; height: 100%; background: linear-gradient(90deg, #3ddc84, #6ee7b7); border-radius: 4px; transition: width .4s; }
.bar.mid > i { background: linear-gradient(90deg, #f5c542, #fbbf24); }
.bar.low > i { background: linear-gradient(90deg, #ef4444, #f87171); }
.pc-xp { margin-top: 5px; }
.pc-xp .bar { height: 4px; }
.pc-xp .bar > i { background: linear-gradient(90deg, #67e8f9, #9b7bff); }
.pc-tag { position: absolute; right: 8px; bottom: 8px; font-family: 'PixelTitle'; font-size: 6px; color: #93a4d8; }
.pc-soul { position: absolute; left: -2px; top: -2px; background: var(--violet); color: #fff; font-family: 'PixelTitle'; font-size: 6px; padding: 3px 5px; border-radius: 5px; box-shadow: 0 0 12px rgba(155,123,255,.8); }

.tabbar { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
.tab {
  font-family: 'PixelTitle'; font-size: 8px; color: #aab6dd; background: #111731;
  border: 2px solid #2b3762; border-radius: 8px; padding: 10px 14px; cursor: pointer;
}
.tab.on { color: #1b1403; background: linear-gradient(180deg,#ffe9a0,#f5c542); border-color: #fff0b8; }
.item-list { display: flex; flex-direction: column; gap: 8px; }
.item-row {
  display: flex; align-items: center; gap: 12px; background: linear-gradient(180deg,#161e3d,#0f142b);
  border: 2px solid #2c3868; border-radius: 10px; padding: 11px 14px; cursor: pointer;
}
.item-row:hover { border-color: #6f86d6; }
.item-ico { width: 34px; height: 34px; border-radius: 8px; background: #2b3762; display: grid; place-items: center; font-size: 22px; }
.item-name { flex: 1; font-family: 'PixelTitle'; font-size: 9px; }
.item-desc { font-size: 20px; color: #aeb9dd; line-height: 1; margin-top: 4px; font-family: 'PixelBody'; }
.item-qty { font-family: 'PixelTitle'; font-size: 9px; color: var(--gold); }
.empty { color: #6b789f; font-size: 26px; text-align: center; padding: 50px 20px; }

/* ---------- shop / dialogs ---------- */
.modal-center {
  position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; z-index: 40;
  background: rgba(3,5,12,.72); backdrop-filter: blur(2px);
}
.modal {
  width: min(620px, 88%);
  background: linear-gradient(180deg, #182046, #0c1124);
  border: 3px solid #e8d9a0;
  border-radius: 14px;
  box-shadow: 0 0 0 3px #141a33, 0 18px 50px rgba(0,0,0,.8);
  padding: 20px 22px;
}
.modal h3 { font-family: 'PixelTitle'; font-size: 13px; color: var(--gold); margin: 0 0 10px; letter-spacing: .5px; }
.modal p { font-size: 25px; color: #dce3f7; margin: 0 0 18px; line-height: 1.1; }
.modal .row { display: flex; gap: 10px; justify-content: flex-end; flex-wrap: wrap; }
.shop-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.shop-item { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border: 2px solid #2c3868; border-radius: 9px; background: #111731; cursor: pointer; }
.shop-item:hover { border-color: var(--gold); }
.shop-item .n { flex: 1; font-family: 'PixelTitle'; font-size: 8px; }
.shop-item .p { font-family: 'PixelTitle'; font-size: 8px; color: var(--gold); }

/* starter picker */
.starters { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }
.starter-card {
  width: 200px; background: linear-gradient(180deg,#1a2450,#0d1329); border: 3px solid #3b4b86;
  border-radius: 14px; padding: 12px; text-align: center; cursor: pointer; transition: .15s;
}
.starter-card:hover { border-color: var(--gold); transform: translateY(-4px); box-shadow: 0 14px 30px rgba(0,0,0,.5); }
.starter-card canvas { width: 128px; height: 128px; image-rendering: pixelated; }
.starter-name { font-family: 'PixelTitle'; font-size: 9px; margin: 4px 0 6px; }
.starter-desc { font-size: 20px; line-height: 1; color: #aeb9dd; min-height: 60px; }
.starter-card .tchip { display: inline-block; margin: 0 2px; }

/* name entry */
.name-input {
  width: 100%; background: #080c1c; border: 3px solid #3b4b86; border-radius: 10px; color: var(--gold);
  font-family: 'PixelTitle'; font-size: 14px; padding: 16px 18px; outline: none; text-align: center; letter-spacing: 2px;
}
.name-input:focus { border-color: var(--gold); }

/* toast */
#toast {
  position: absolute; top: 16px; left: 50%; transform: translateX(-50%) translateY(-12px);
  z-index: 50; background: linear-gradient(180deg,#22305e,#101731); border: 2px solid var(--gold);
  color: #fff; border-radius: 10px; padding: 11px 20px; font-family: 'PixelTitle'; font-size: 8px;
  opacity: 0; pointer-events: none; transition: .25s; box-shadow: 0 8px 24px rgba(0,0,0,.6);
  text-align: center; max-width: 80%;
}
#toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* fade */
#fade { position: absolute; inset: 0; background: #05060c; opacity: 0; pointer-events: none; z-index: 60; transition: opacity .35s; }
#fade.on { opacity: 1; pointer-events: auto; }
#flash { position: absolute; inset: 0; background: #fff; opacity: 0; pointer-events: none; z-index: 55; }
#flash.go { animation: flashAnim .5s ease-out; }
@keyframes flashAnim { 0% { opacity: .95; } 100% { opacity: 0; } }

/* log */
.battlelog { font-size: 24px; line-height: 1.08; }
.battlelog .hl { color: var(--gold); }

/* credits */
.credits-scroll { overflow: hidden; position: relative; height: 100%; }
.credits-inner { animation: creditScroll 40s linear infinite; text-align: center; font-size: 25px; color: #dfe6fb; }
@keyframes creditScroll { from { transform: translateY(100%); } to { transform: translateY(-100%); } }

@media (max-width: 760px) {
  #hint { display: none; }
  #gameframe { width: 100vw; border-radius: 0; box-shadow: none; }
  #app { padding: 0; }
  .screen { padding: 16px; }
  .screen-title { font-size: 15px; }
  .party-grid { grid-template-columns: 1fr; }
  .battle-cmd { width: 260px; }
  .title-menu { bottom: 4%; }
}

