cd /home/runner/work/Pokemon/Pokemon && node -e "
const fs=require('fs'); const vm=require('vm');
const ctx={console}; vm.createContext(ctx);
for(const f of ['js/core.js','js/data.js']) vm.runInContext(fs.readFileSync(f,'utf8'),ctx);
const missing=new Set();
for(const s of Object.values(ctx.SPECIES)) for(const m of s.moves) if(!ctx.MOVES[m]) missing.add(m);
console.log('missing moves', [...missing]);
const ab=new Set(); for(const s of Object.values(ctx.SPECIES)) if(!ctx.ABILITIES[s.ability]) ab.add(s.ability);
console.log('missing abilities', [...ab]);
const tr=new Set(); for(const t of Object.values(ctx.TRAINERS)) for(const [s,l] of t.team) if(!ctx.SPECIES[s]) tr.add(s);
console.log('missing trainer species', [...tr]);
const en=new Set(); for(const arr of Object.values(ctx.ENCOUNTERS)) for(const e of arr) if(!ctx.SPECIES[e.sp]) en.add(e.sp);
console.log('missing encounter species', [...en]);
console.log('species',Object.keys(ctx.SPECIES).length,'trainers',Object.keys(ctx.TRAINERS).length,'moves',Object.keys(ctx.MOVES).length,'awakenings',Object.keys(ctx.AWAKENINGS).length);
"

