33:       }
34:       tiles.push(row); collision.push(block);
35:     }
36:     const map = { id, name, width, height, theme, encounter: encounter || null, tiles, collision, objects: [], npcs: [], doors: [], warps: [] };
37:     // Natural boundary keeps the player on the authored map.
38:     for (let x = 0; x < width; x++) { map.collision[0][x] = true; map.collision[height - 1][x] = true; }
39:     for (let y = 0; y < height; y++) { map.collision[y][0] = true; map.collision[y][width - 1] = true; }
