79: const Sound = {
80:   ctx: null, master: null, musicGain: null, sfxGain: null,
81:   musicOn: true, sfxOn: true, track: null, loopTimer: null, noiseBuf: null, beat: 0,
82: 
83:   init() {
84:     if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
85:     const AC = window.AudioContext || window.webkitAudioContext;
86:     if (!AC) return;
87:     this.ctx = new AC();
88:     this.master = this.ctx.createGain(); this.master.gain.value = 0.55; this.master.connect(this.ctx.destination);
89:     this.musicGain = this.ctx.createGain(); this.musicGain.gain.value = this.musicOn ? 0.34 : 0; this.musicGain.connect(this.master);
90:     this.sfxGain = this.ctx.createGain(); this.sfxGain.gain.value = this.sfxOn ? 0.5 : 0; this.sfxGain.connect(this.master);
91:     // noise buffer
92:     const len = this.ctx.sampleRate * 0.6;
93:     this.noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
94:     const d = this.noiseBuf.getChannelData(0);
95:     for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
96:   },
97:   setMusic(on) { this.musicOn = on; if (this.musicGain) this.musicGain.gain.setTargetAtTime(on ? 0.34 : 0, this.ctx.currentTime, .05); },
98:   setSfx(on) { this.sfxOn = on; if (this.sfxGain) this.sfxGain.gain.setTargetAtTime(on ? 0.5 : 0, this.ctx.currentTime, .05); },
99:   note(freq, dur, type = 'square', vel = .2, when = 0, target = null, slide = 0) {
100:     if (!this.ctx) return;
101:     const t = this.ctx.currentTime + when;
102:     const o = this.ctx.createOscillator();
103:     const g = this.ctx.createGain();
104:     o.type = type; o.frequency.setValueAtTime(freq, t);
105:     if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
106:     g.gain.setValueAtTime(0.0001, t);
107:     g.gain.exponentialRampToValueAtTime(vel, t + 0.012);
108:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur * 1.55);
109:     o.connect(g); g.connect(target || this.musicGain);
110:     o.start(t); o.stop(t + dur * 1.7);
111:   },
112:   drum(when = 0, kind = 'kick', vel = .35) {
113:     if (!this.ctx) return;
114:     const t = this.ctx.currentTime + when;
115:     if (kind === 'kick') {
116:       const o = this.ctx.createOscillator(), g = this.ctx.createGain();
117:       o.type = 'sine'; o.frequency.setValueAtTime(130, t); o.frequency.exponentialRampToValueAtTime(38, t + .12);
118:       g.gain.setValueAtTime(vel, t); g.gain.exponentialRampToValueAtTime(0.001, t + .16);
119:       o.connect(g); g.connect(this.musicGain); o.start(t); o.stop(t + .18);
120:     } else {
121:       const s = this.ctx.createBufferSource(), g = this.ctx.createGain(), f = this.ctx.createBiquadFilter();
122:       s.buffer = this.noiseBuf; f.type = kind === 'hat' ? 'highpass' : 'bandpass'; f.frequency.value = kind === 'hat' ? 7500 : 1800;
123:       g.gain.setValueAtTime(vel, t); g.gain.exponentialRampToValueAtTime(0.001, t + (kind === 'hat' ? .05 : .12));
124:       s.connect(f); f.connect(g); g.connect(this.musicGain); s.start(t); s.stop(t + .14);
125:     }
126:   },
127:   midiFreq(m) { return 440 * Math.pow(2, (m - 69) / 12); },
128: 
129:   playTrack(name, opts = {}) {
130:     this.init();
131:     if (this.track === name && !opts.force) return;
132:     this.track = name;
133:     clearTimeout(this.loopTimer);
134:     if (!this.ctx) return;
135:     const tr = TRACKS[name] || TRACKS.town;
136:     this.beat = 0;
137:     const step = 60 / tr.bpm / 2;        // eighth-note
138:     const steps = tr.lead.length;
139:     const loopBeats = steps * step;
140: 
141:     const playLoop = () => {
142:       if (this.track !== name) return;
143:       const now = 0;
144:       // lead
145:       tr.lead.forEach((n, i) => {
146:         if (n === null || n === undefined) return;
147:         const f = this.midiFreq(tr.root + tr.scale[n % tr.scale.length] + 12 * Math.floor(n / tr.scale.length));
148:         this.note(f, step * 0.92, tr.leadWave || 'square', tr.leadVol || .16, i * step);
149:         if (tr.echo) this.note(f, step * .7, 'triangle', .05, i * step + step * 0.75);
150:       });
151:       // bass
152:       (tr.bass || []).forEach((n, i) => {
153:         if (n === null) return;
154:         const f = this.midiFreq(tr.root - 12 + tr.scale[n % tr.scale.length] + 12 * Math.floor(n / tr.scale.length));
155:         this.note(f, step * 1.8, 'triangle', .22, i * step * (tr.bassStep || 2));
156:       });
157:       // pad
158:       if (tr.pad) tr.pad.forEach((chord, i) => {
159:         chord.forEach(n => {
160:           const f = this.midiFreq(tr.root + tr.scale[0] + n);
161:           this.note(f, loopBeats / tr.pad.length * .95, 'sine', .055, i * loopBeats / tr.pad.length);
162:         });
163:       });
164:       // drums
165:       if (tr.drums) {
166:         for (let i = 0; i < steps; i++) {
167:           const d = tr.drums[i % tr.drums.length];
168:           if (d === 'k') this.drum(i * step, 'kick', .32);
169:           if (d === 's') this.drum(i * step, 'snare', .16);
170:           if (d === 'h') this.drum(i * step, 'hat', .07);
171:         }
172:       }
173:       this.loopTimer = setTimeout(playLoop, loopBeats * 1000 - 30);
174:     };
175:     playLoop();
176:   },
177:   stopMusic() { this.track = null; clearTimeout(this.loopTimer); },
178:   sfx(name) {
179:     this.init();
180:     if (!this.ctx || !this.sfxOn) return;
181:     const t = this.ctx.currentTime;
182:     const beep = (f, dur, type = 'square', vel = .16, when = 0, slide = 0) => this.note(f, dur, type, vel, when, this.sfxGain, slide);
183:     switch (name) {
184:       case 'blip': beep(760, .03, 'square', .06); break;
185:       case 'select': beep(520, .05, 'square', .12); beep(880, .07, 'square', .11, .05); break;
186:       case 'back': beep(420, .06, 'square', .1); beep(280, .07, 'square', .08, .05); break;
187:       case 'hit': this.drum(0, 'snare', .3); beep(180, .08, 'sawtooth', .16, 0, -80); break;
188:       case 'super': this.drum(0, 'snare', .4); beep(250, .12, 'sawtooth', .2, 0, -140); beep(120, .18, 'square', .15, .06, -60); break;
189:       case 'heal': [523,659,784,1047].forEach((f,i)=>beep(f,.16,'sine',.13,i*.09)); break;
190:       case 'ball': beep(300, .18, 'sine', .15, 0, 500); break;
191:       case 'catch': [523,659,784,1047,1319].forEach((f,i)=>beep(f,.18,'square',.12,i*.1)); break;
192:       case 'faint': beep(440, .5, 'square', .12, 0, -380); break;
193:       case 'level': [523,659,784,1047].forEach((f,i)=>beep(f,.14,'square',.15,i*.08)); break;
194:       case 'awaken': {
195:         const o = this.ctx.createOscillator(), g = this.ctx.createGain();
196:         o.type = 'sawtooth'; o.frequency.setValueAtTime(80, t); o.frequency.exponentialRampToValueAtTime(1400, t + .9);
197:         g.gain.setValueAtTime(.001, t); g.gain.exponentialRampToValueAtTime(.22, t + .2); g.gain.exponentialRampToValueAtTime(.001, t + 1.2);
198:         o.connect(g); g.connect(this.sfxGain); o.start(t); o.stop(t + 1.3);
199:         [392,523,659,784,1047].forEach((f,i)=>beep(f,.4,'square',.1,.35+i*.09));
200:         break;
201:       }
202:       case 'encounter': [784,659,784,988].forEach((f,i)=>beep(f,.11,'square',.16,i*.1)); break;
203:       case 'badge': [523,659,784,1047,1319,1568].forEach((f,i)=>beep(f,.22,'square',.13,i*.11)); break;
204:       case 'soul': [220,330,440,660,880].forEach((f,i)=>beep(f,.3,'sine',.1,i*.06)); break;
205:       case 'open': beep(620,.05,'square',.09); beep(930,.07,'square',.08,.04); break;
206:       case 'buy': beep(880,.06,'square',.12); beep(1175,.09,'square',.1,.06); break;
207:       case 'nope': beep(200,.12,'square',.14); break;
208:     }
209:   }
210: };
