334:   function calculateDamage(user, target, move) {
335:     if (!move || !move.power) return { damage:0, effectiveness:1, critical:false };
336:     const def = ability(target), userAbility = ability(user);
337:     const atkStat = move.cat === 'spec' ? 'spa' : 'atk';
338:     const defStat = move.cat === 'spec' ? 'spd' : 'def';
339:     let effectiveness = typeEff(move.type, types(target));
340:     if (def.immune?.includes(move.type)) effectiveness = 0;
341:     if (def.absorb === move.type) return { damage:0, effectiveness:0, absorbed:true, heal:true, critical:false };
342:     let power = move.power;
343:     if (userAbility.pinch === move.type && user.hp <= user.maxHp / 3) power *= 1.5;
344:     if (userAbility.boost && (userAbility.boost.type === move.type || userAbility.boost.type === 'all')) power *= userAbility.boost.mult;
345:     if (def.resist?.[move.type]) effectiveness *= def.resist[move.type];
346:     if (def.multiscale && target.hp === target.maxHp) effectiveness *= .5;
347:     const critChance = .04 * (1 + number(move.crit, 0) + number(userAbility.crit, 0));
348:     const critical = Math.random() < critChance;
349:     const randomFactor = .85 + Math.random() * .15;
350:     const stab = types(user).includes(move.type) ? 1.5 : 1;
351:     const base = Math.floor((((2 * user.level / 5 + 2) * power * statValue(user, atkStat) / statValue(target, defStat)) / 50) + 2);
352:     const damage = effectiveness === 0 ? 0 : Math.max(1, Math.floor(base * effectiveness * stab * (critical ? 1.5 : 1) * randomFactor));
