394:         if (move.recoil) user.hp = Math.max(0, user.hp - Math.max(1, Math.floor(damage * move.recoil)));
395:         if (move.contact) {
396:           const contact = ability(target);
397:           if (contact.contactRecoil) user.hp = Math.max(0, user.hp - Math.max(1, Math.floor(user.maxHp * contact.contactRecoil)));
398:           if (contact.contact && Math.random() * 100 < contact.contact.chance) updateStatus(session, user, contact.contact.status);
399:         }
400:       }
401:       const retaliatory = ability(target).onHitBy;
402:       if (retaliatory?.type === move.type) changeStage(session, target, retaliatory.stat, retaliatory.stages);
403:     }
404:     if (move.recharge) user.recharge = true;
405:     if (move.cat === 'status' || target.hp > 0) applyMoveEffects(session, user, target, move, result);
