413:   async function grantExperience(session, winner, defeated) {
414:     const data = speciesData(defeated);
415:     const gain = Math.max(1, Math.floor(number(data.xpYield, 50) * defeated.level / 7 * (session.wild ? 1 : 1.5)));
416:     winner.xp = number(winner.xp, 0) + gain;
417:     await message(session, `${memberName(winner)} gained ${gain} EXP!`);
418:     while (winner.xp >= winner.level ** 3 && winner.level < 100) {
419:       winner.xp -= winner.level ** 3;
420:       winner.level++;
421:       const oldMax = winner.maxHp;
422:       refreshStats(winner, true);
423:       winner.hp = Math.min(winner.maxHp, winner.hp + winner.maxHp - oldMax);
424:       await message(session, `${memberName(winner)} grew to level ${winner.level}!`);
425:       const evo = speciesData(winner).evolve;
426:       if (evo && winner.level >= evo[1] && SPECIES[evo[0]]) await evolve(session, winner, evo[0]);
427:     }
