31: function saveGame() {
32:   if (!Game.started) return false;
33:   const payload = {
34:     version: 1,
35:     party: Game.party,
36:     inventory: Game.inventory,
37:     player: Game.player,
38:     flags: Game.flags,
39:     storage: Game.storage,
40:     world: {
