122: async function beginNewGame() {
123:   titleActive = false;
124:   UI.close();
125:   Game.state = 'starting';
126:   if (await chooseStarter()) {
127:     Game.state = 'overworld';
128:     await UI.say('Welcome to Aurelia. Professor Cedar is waiting in the village lab.', 'Aurelia');
129:     World.draw();
130:   } else {
131:     titleActive = true; Game.state = 'title'; showTitle();
132:   }
133: }
