135: async function continueGame() {
136:   const save = readSave();
137:   if (!save) { toast('No save data found.'); return; }
138:   titleActive = false; UI.close();
139:   if (applySave(save)) { Game.state = 'overworld'; World.draw(); toast('Save data loaded.'); }
140:   else { titleActive = true; showTitle(); toast('That save file is invalid.'); }
141: }
