143: function showTitle() {
144:   titleActive = true; Game.state = 'title'; titleCanvas();
145:   const hasSave = !!readSave();
146:   UI.menu('Pokémon Eclipse', [
147:     { label: 'New Game', value: 'new' },
148:     { label: 'Continue', value: 'continue', disabled: !hasSave },
149:     { label: 'How to Play', value: 'help' }
150:   ], { description: 'Aurelia Genesis', footer: 'A journey beyond the eclipse' }).then(async choice => {
151:     if (!titleActive) return;
152:     if (choice === 'new') await beginNewGame();
153:     else if (choice === 'continue') await continueGame();
154:     else if (choice === 'help') {
155:       await UI.say('Move with arrows or WASD. Face a person or object and press Z or Enter to interact. Press X or Escape for your Pokémon menu. Tall grass hides wild Pokémon.', 'Guide');
156:       showTitle();
157:     }
158:   });
159: }
