161: async function partyMenu() {
162:   const labels = Game.party.map(mon => `${mon.name} Lv.${mon.level}  ${Math.max(0, mon.hp)}/${mon.maxHp} HP`);
163:   labels.push({ label: 'Save Game', value: 'save' }, { label: 'Close', value: 'close' });
164:   const result = await UI.menu('Trainer Menu', labels, { footer: 'Z / Enter select · X / Esc close' });
165:   if (result === 'save') saveGame();
166:   else if (result && result !== 'close') {
167:     const mon = Game.party.find(p => p.name === result.split(' Lv.')[0]);
168:     if (mon) await UI.say(`${mon.name} is ready for adventure!`, 'Party');
169:   }
170: }
