172: function onPress(key) {
173:   if (key === 'm') {
174:     Sound.musicOn = !Sound.musicOn;
175:     if (Sound.musicOn) Sound.playTrack(Game.state === 'overworld' ? 'town' : 'title');
176:     else Sound.stopMusic();
177:     toast(Sound.musicOn ? 'Music on.' : 'Music muted.');
178:     return;
179:   }
180:   if (titleActive || UI.active || Battle.busy) return;
181:   if (key === 'z' || key === 'enter') { World.interact(); return; }
182:   if (key === 'x' || key === 'escape') { partyMenu(); return; }
183: }
184: 
185: function heldMovement(now) {
186:   if (titleActive || UI.active || Battle.busy || Game.state !== 'overworld') return;
187:   if (now - lastStep < 135) return;
188:   let dx = 0, dy = 0;
189:   if (Input.down('arrowup', 'w')) dy = -1;
190:   else if (Input.down('arrowdown', 's')) dy = 1;
191:   else if (Input.down('arrowleft', 'a')) dx = -1;
192:   else if (Input.down('arrowright', 'd')) dx = 1;
193:   if (dx || dy) { World.step(dx, dy); lastStep = now; }
194: }
195: 
196: function loop(now) {
197:   const dt = Math.min(100, now - (loop._last || now)); loop._last = now;
198:   heldMovement(now);
199:   if (!titleActive) { World.update(dt); World.draw(); }
200:   requestAnimationFrame(loop);
201: }
202: 
203: function boot() {
204:   Input.onPress(onPress);
205:   Sound.playTrack('title');
206:   showTitle();
207:   requestAnimationFrame(loop);
208: }
209: 
210: document.addEventListener('DOMContentLoaded', boot, { once: true });

